    if (!keyEdit.TryGetProperty("crossLevelTemplate", out JsonElement keyTemplate) ||
        ReadJsonString(keyTemplate, "id") != key.CrossLevelTemplateId ||
        ReadJsonString(keyTemplate, "family") != key.CrossLevelFamily ||
