        ["family"] = "springChest",
        ["sourceLevelKey"] = "PeaceKeepers",
        ["sourceLevelName"] = "Peace Keepers",
        ["sourceTrueIndex"] = 113,
        ["addSupportStatus"] = "experimental-actor-package-swap",
        ["requiredExporterFeature"] = "ActorPackageSwapIntoUnusedRoot"
